// ── 🏷️ ETIQUETAS ────────────────────────────────────────────
// Dos sub-modos: Producto (anexado desde etiquetas_producto.html, antes
// standalone con su propio login — ya no necesita login ni cliente
// Supabase propio, usa pmDB y la sesión de PanMaestro directo) y Marca
// (etiqueta fija de negocio: logo + redes + QR, no toca Supabase).
// La impresión de ambos modos abre una ventana aparte (mismo patrón que
// docImprimirNota/repComImprimir en reportes.js) en vez de @media print,
// para no chocar con el CSS de impresión de la app principal.

function etMostrar(id) {
  ['et-producto-wrap','et-marca-wrap'].forEach(v => {
    const el = document.getElementById(v);
    if (el) el.style.display = v===id ? 'block' : 'none';
  });
  if (id === 'et-marca-wrap') etmkRenderPreview();
}

let etProductos = [];
let etActual = null;

async function etCargarCatalogo() {
  const sel = document.getElementById('et-producto');
  if (!sel) return;
  try {
    const data = await pmDB.get('productos_terminados',
      { activo: true },
      'codigo,nombre,peso_g,precio_full,es_masa_madre'
    );
    etProductos = (data || []).sort((a,b) => (a.codigo||'').localeCompare(b.codigo||''));
    sel.innerHTML = '<option value="">Seleccioná un producto…</option>' +
      etProductos.map((p, i) => `<option value="${i}">${pmEsc(p.codigo)} — ${pmEsc(p.nombre)}</option>`).join('');
  } catch(e) {
    sel.innerHTML = '<option>Error cargando catálogo</option>';
    pmToast('Error al cargar catálogo: ' + e.message, 'err');
  }
}

function etSeleccionar(idx) {
  if (idx === '') { etActual = null; document.getElementById('et-btn-imprimir').disabled = true; return; }
  etActual = etProductos[Number(idx)];
  if (!etActual) return;
  document.getElementById('et-peso').value   = etActual.peso_g ?? '';
  document.getElementById('et-precio').value = etActual.precio_full ?? '';
  etActualizarPreview();
  document.getElementById('et-btn-imprimir').disabled = false;
}

function etActualizarPreview() {
  const nombre = etActual ? etActual.nombre : '—';
  const pesoVal   = document.getElementById('et-peso').value;
  const precioVal = document.getElementById('et-precio').value;
  const peso   = pesoVal ? `${pesoVal} g` : '—';
  const precio = precioVal ? `₡${Number(precioVal).toLocaleString('es-CR')}` : '—';
  const esMM   = etActual ? !!etActual.es_masa_madre : false;

  document.getElementById('et-p-nombre').textContent = nombre;
  document.getElementById('et-p-peso').textContent   = peso;
  document.getElementById('et-p-precio').textContent = precio;

  const badge = document.getElementById('et-mm-badge');
  badge.classList.toggle('off', !esMM);

  const preview = document.getElementById('et-preview');
  let mmEl = preview.querySelector('.et-mm');
  if (esMM) {
    if (!mmEl) {
      mmEl = document.createElement('div');
      mmEl.className = 'et-mm';
      mmEl.textContent = 'MASA MADRE';
      preview.querySelector('.et-fila').appendChild(mmEl);
    }
  } else if (mmEl) {
    mmEl.remove();
  }
}

function etImprimir() {
  if (!etActual) return;
  const cantidad = Math.max(1, parseInt(document.getElementById('et-cantidad').value) || 1);
  const pesoVal   = document.getElementById('et-peso').value;
  const precioVal = document.getElementById('et-precio').value;
  const peso   = pesoVal ? `${pesoVal} g` : '';
  const precio = precioVal ? `₡${Number(precioVal).toLocaleString('es-CR')}` : '';
  const esMM   = !!etActual.es_masa_madre;

  const CSS = `
    *{box-sizing:border-box;margin:0;padding:0}
    body{font-family:-apple-system,'Segoe UI',Roboto,sans-serif}
    .label{width:7cm;height:4cm;border:2px solid #000;padding:0.3cm;display:flex;flex-direction:column;justify-content:space-between;background:#fff;page-break-after:always}
    .label:last-child{page-break-after:auto}
    .nombre{font-size:22px;font-weight:600;line-height:1.15}
    .fila{display:flex;gap:0.25cm;align-items:center}
    .campo{border:1px solid #000;border-radius:4px;padding:0.12cm 0.25cm;flex:1}
    .campo .k{font-size:9px;color:#555}
    .campo .v{font-size:15px;font-weight:600}
    .mm{border:2px solid #000;border-radius:20px;padding:0.1cm 0.3cm;font-size:11px;font-weight:700;text-align:center;white-space:nowrap}
    @page{size:7cm 4cm;margin:0}
  `;

  const unaEtiqueta = `
    <div class="label">
      <div class="nombre">${pmEsc(etActual.nombre)}</div>
      <div class="fila">
        <div class="campo"><div class="k">peso</div><div class="v">${peso}</div></div>
        <div class="campo"><div class="k">precio</div><div class="v">${precio}</div></div>
        ${esMM ? '<div class="mm">MASA MADRE</div>' : ''}
      </div>
    </div>`;

  const win = window.open('', '_blank');
  win.document.write(`<!DOCTYPE html><html><head>
    <meta charset="UTF-8">
    <title>Etiquetas — ${pmEsc(etActual.nombre)}</title>
    <style>${CSS}</style>
  </head><body>${unaEtiqueta.repeat(cantidad)}<script>window.onload=()=>{window.print();}<\/script></body></html>`);
  win.document.close();
}

// ── 🏷️ ETIQUETAS DE MARCA ──────────────────────────────────
// Etiqueta fija (no varía por producto): logo + nombre + redes + QR.
// El QR es una vCard (nombre + telefono/WhatsApp + ubicacion) - al
// escanearla el celular ofrece guardar el contacto directo. Datos hoy
// fijos en el codigo; si mas adelante se conecta a una pagina web o a
// Supabase, solo cambia ETMK_DATOS/etmkVcard(), no el layout.

const ETMK_LOGO = 'data:image/png;base64,';

const ETMK_DATOS = {
  nombre: "Victor's Bakery & Sweets",
  telefono: '+50670565587',
  ubicacion: 'San Joaquin de Flores, Costa Rica',
  redes: [
    { icono: 'f', label: 'Facebook' },
    { icono: 'i', label: 'Instagram' }
  ]
};

function etmkVcard() {
  return [
    'BEGIN:VCARD',
    'VERSION:3.0',
    `FN:${ETMK_DATOS.nombre}`,
    `TEL;TYPE=CELL:${ETMK_DATOS.telefono}`,
    `ADR:;;${ETMK_DATOS.ubicacion};;;;`,
    'END:VCARD'
  ].join('\n');
}

function etmkRedesHTML() {
  return ETMK_DATOS.redes.map(r =>
    `<span class="et-mk-red"><b>${pmEsc(r.icono)}</b> ${pmEsc(r.label)}</span>`
  ).join('');
}

function etmkRenderPreview() {
  const logoImg = document.getElementById('et-mk-logo-img');
  const nombreEl = document.getElementById('et-mk-nombre');
  const redesEl = document.getElementById('et-mk-redes');
  if (logoImg) logoImg.src = ETMK_LOGO;
  if (nombreEl) nombreEl.textContent = ETMK_DATOS.nombre;
  if (redesEl) redesEl.innerHTML = etmkRedesHTML();

  const cont = document.getElementById('et-mk-qr-preview');
  if (!cont || typeof QRCode === 'undefined') return;
  cont.innerHTML = '';
  new QRCode(cont, { text: etmkVcard(), width: 96, height: 96, correctLevel: QRCode.CorrectLevel.M });
}

function etmkImprimir() {
  const cantidad = Math.max(1, parseInt(document.getElementById('et-mk-cantidad').value) || 1);

  const CSS = `
    *{box-sizing:border-box;margin:0;padding:0}
    html,body{width:4cm}
    body{font-family:-apple-system,'Segoe UI',Roboto,sans-serif}
    .label{width:4cm;height:7cm;padding:0.25cm;display:flex;flex-direction:column;align-items:center;justify-content:space-evenly;background:#fff;overflow:hidden;page-break-after:always}
    .label:last-child{page-break-after:auto}
    .logo{width:1.8cm;height:1.8cm;border-radius:50%;object-fit:cover;flex-shrink:0}
    .nombre{font-size:12px;font-weight:600;text-align:center;line-height:1.2}
    .redes{display:flex;flex-direction:column;align-items:center;gap:0.08cm;font-size:9px;color:#333}
    #qr{width:2.3cm;height:2.3cm;display:flex;align-items:center;justify-content:center;flex-shrink:0}
    #qr img,#qr canvas{width:100%;height:100%}
    @page{size:4cm 7cm;margin:0}
  `;

  const unaEtiqueta = `
    <div class="label">
      <img class="logo" src="${ETMK_LOGO}">
      <div class="nombre">${pmEsc(ETMK_DATOS.nombre)}</div>
      <div class="redes">${etmkRedesHTML()}</div>
      <div id="qr"></div>
    </div>`;

  const win = window.open('', '_blank');
  win.document.write(`<!DOCTYPE html><html><head>
    <meta charset="UTF-8">
    <title>Etiqueta de marca -- ${pmEsc(ETMK_DATOS.nombre)}</title>
    <style>${CSS}</style>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"><\/script>
  </head><body>${unaEtiqueta.repeat(cantidad)}<script>
    window.onload = () => {
      document.querySelectorAll('#qr').forEach(el => {
        new QRCode(el, { text: ${JSON.stringify(etmkVcard())}, width: 130, height: 130, correctLevel: QRCode.CorrectLevel.M });
      });
      setTimeout(() => window.print(), 200);
    };
  <\/script></body></html>`);
  win.document.close();
}

